module firr20_v6 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg  [7:0]  xs [0:19];
    integer     i;
    reg  [31:0] acc;
    always @(*) acc = 8'd1 * xs[0] + 8'd5 * xs[1] + 8'd13 * xs[2] + 8'd25 * xs[3] + 8'd41 * xs[4] + 8'd61 * xs[5] + 8'd85 * xs[6] + 8'd113 * xs[7] + 8'd145 * xs[8] + 8'd181 * xs[9] + 8'd221 * xs[10] + 8'd265 * xs[11] + 8'd313 * xs[12] + 8'd365 * xs[13] + 8'd421 * xs[14] + 8'd481 * xs[15] + 8'd545 * xs[16] + 8'd613 * xs[17] + 8'd685 * xs[18] + 8'd761 * xs[19];
    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 20; i = i + 1) xs[i] <= 8'd0;
            y <= 16'd0;
        end else begin
            xs[0] <= x;
            for (i = 1; i < 20; i = i + 1) xs[i] <= xs[i-1];
            y <= acc[15:0];
        end
    end
endmodule

